import{_ as e,o as a,c as l,a5 as n}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"752-批量复制文件及文件夹到多个文件夹","日期":"2026-04-08T00:00:00.000Z","修改日期":"2026-04-08T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["文件复制","文件复制到多个文件夹","文件夹复制","文件夹复制到多个文件夹"]},"headers":[{"level":2,"title":"752-批量复制文件及文件夹到多个文件夹","slug":"_752-批量复制文件及文件夹到多个文件夹","link":"#_752-批量复制文件及文件夹到多个文件夹","children":[{"level":3,"title":"📑 使用场景例子展示","slug":"📑-使用场景例子展示","link":"#📑-使用场景例子展示","children":[]},{"level":3,"title":"📑 程序使用环境及相关说明","slug":"📑-程序使用环境及相关说明","link":"#📑-程序使用环境及相关说明","children":[]},{"level":3,"title":"📑 程序截图","slug":"📑-程序截图","link":"#📑-程序截图","children":[]},{"level":3,"title":"📑 视频演示","slug":"📑-视频演示","link":"#📑-视频演示","children":[]}]}],"relativePath":"md/文件及文件夹批处理/752-批量复制文件及文件夹到多个文件夹.md","filePath":"md/文件及文件夹批处理/752-批量复制文件及文件夹到多个文件夹.md"}'),o={name:"md/文件及文件夹批处理/752-批量复制文件及文件夹到多个文件夹.md"};function p(r,t,i,s,g,c){return a(),l("div",null,[...t[0]||(t[0]=[n('<h2 id="_752-批量复制文件及文件夹到多个文件夹" tabindex="-1">752-批量复制文件及文件夹到多个文件夹 <a class="header-anchor" href="#_752-批量复制文件及文件夹到多个文件夹" aria-label="Permalink to &quot;752-批量复制文件及文件夹到多个文件夹&quot;">​</a></h2><p>一对多（一个文件或多个文件或一个文件夹或多个文件夹）文件夹或文件复制工具</p><p>批量复制文件或文件夹到多个文件夹内，支持目标文件夹下子文件夹穿透</p><p>**选项1：**选择文件进行复制，可以同时选择多个文件，url文件复制时按照下方方式进行</p><p>下拉选择url，然后选择url文件，url文件需要单需选择，不能和其他文件类型同时选择，这是win电脑的通病，无法解决。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/p8zZFUYiVLrcfDa.png" alt="null" title="image-20241015161547031"></p><p>**还可以通过如下方式进行：**在输入框中手动输入</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/8SWZdkIH9wfvrLR.png" alt="null" title="image-20241015161800072"></p><p>格式如：E:\\桌面\\ceshi\\1.url, E:\\桌面\\ceshi\\1：11.url 每个文件简使用, 隔开</p><p>**选项2：**同时复制文件夹本身以及文件夹下所有文件，选择文件夹即可</p><p>比如A文件夹下是需要复制的文件或文件夹，则会将A文件夹包括文件夹内的内容整个复制。</p><p><strong>如图所示,复制的是文件夹和文件夹内的内容</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/vV473T2NdjFfiR5.png" alt="null" title="image-20241108230945656"></p><p>**选项3：**复制文件夹下所有文件及文件夹，只需要输入文件夹路径，就会将文件夹下所有文件进行复制</p><p>比如A文件夹下是需要复制的文件或文件夹，会将A文件夹下所有内容复制。</p><p><strong>如图所示,复制的是文件夹内的内容</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/YofHRAJ91kVgXwI.png" alt="null" title="image-20241108231223957"></p><p>**目标文件夹路径：**比如A文件夹下有很多个文件夹，则会将文件或文件夹同时复制多A文件夹下所有文件夹内</p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多支持的文件，同时有B、C、D….等文件夹，B、C、D….等这些文件夹下边还有子文件夹，子文件夹下也有支持的文件。</p><p>只需要输入A文件夹路径即可。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/2vfGupemDP81Jl4.png" alt="null" title="image-20241015161252881"></p><h3 id="📑-视频演示" tabindex="-1">📑 视频演示 <a class="header-anchor" href="#📑-视频演示" aria-label="Permalink to &quot;📑 视频演示&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV16DDaYdEtz/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV16DDaYdEtz/</a></p><p>📑 本工具下载地址</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/391.html" target="_blank" rel="noreferrer">https://www.softbangong.com/391.html</a></p>',30)])])}const _=e(o,[["render",p]]);export{d as __pageData,_ as default};
